#!/usr/bin/env python3
"""
Minimal agentic loop with Anthropic API, bash execution tool, and human confirmation.
"""

import os
import sys
import json
import subprocess
from typing import Dict, List, Optional
from anthropic import Anthropic

class BashTool:
    """Tool for executing bash commands with user confirmation."""

    @staticmethod
    def run(command: str) -> Dict[str, str]:
        """Execute a bash command after user confirmation."""
        print(f"\n🔧 Tool Request: Execute Bash Command")
        print(f"Command: {command}")
        print("-" * 50)

        while True:
            confirmation = input("Execute this command? (y/n): ").lower().strip()
            if confirmation == 'y':
                try:
                    result = subprocess.run(
                        command,
                        shell=True,
                        capture_output=True,
                        text=True,
                        timeout=30
                    )
                    output = result.stdout if result.stdout else result.stderr
                    return {
                        "status": "success",
                        "output": output,
                        "return_code": str(result.returncode)
                    }
                except subprocess.TimeoutExpired:
                    return {
                        "status": "error",
                        "output": "Command timed out after 30 seconds"
                    }
                except Exception as e:
                    return {
                        "status": "error",
                        "output": f"Error executing command: {str(e)}"
                    }
            elif confirmation == 'n':
                return {
                    "status": "cancelled",
                    "output": "Command execution cancelled by user"
                }
            else:
                print("Please enter 'y' for yes or 'n' for no.")

class AgentLoop:
    """Minimal agentic loop using Anthropic API."""

    def __init__(self, api_key: Optional[str] = None):
        """Initialize the agent with Anthropic client."""
        self.client = Anthropic(api_key=api_key or os.getenv("ANTHROPIC_API_KEY"))
        self.tools = [
            {
                "name": "run_bash",
                "description": "Execute a bash command on the system",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "command": {
                            "type": "string",
                            "description": "The bash command to execute"
                        }
                    },
                    "required": ["command"]
                }
            }
        ]
        self.conversation = []

    def process_tool_use(self, tool_use: Dict) -> Dict:
        """Process a tool use request from the assistant."""
        tool_name = tool_use.get("name")
        tool_input = tool_use.get("input", {})

        if tool_name == "run_bash":
            command = tool_input.get("command", "")
            return BashTool.run(command)
        else:
            return {
                "status": "error",
                "output": f"Unknown tool: {tool_name}"
            }

    def run(self):
        """Main agent loop."""
        print("🤖 Minimal Agent Loop")
        print("Type 'exit' or 'quit' to end the conversation")
        print("-" * 50)

        while True:
            # Get user input
            user_input = input("\n👤 You: ").strip()

            if user_input.lower() in ['exit', 'quit']:
                print("\n👋 Goodbye!")
                break

            if not user_input:
                continue

            # Add user message to conversation
            self.conversation.append({
                "role": "user",
                "content": user_input
            })

            try:
                # Get response from Claude
                response = self.client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=4096,
                    tools=self.tools,
                    messages=self.conversation
                )

                # Add assistant response to conversation
                self.conversation.append({
                    "role": "assistant",
                    "content": response.content
                })

                # Process the response
                tool_results = []
                has_text = False

                for content_block in response.content:
                    if content_block.type == "text":
                        if content_block.text.strip():
                            has_text = True
                            print(f"\n🤖 Assistant: {content_block.text}")

                    elif content_block.type == "tool_use":
                        # Execute the tool
                        tool_result = self.process_tool_use(content_block)
                        tool_results.append({
                            "tool_use_id": content_block.id,
                            "content": json.dumps(tool_result)
                        })

                # If there were tool uses, send the results back
                if tool_results:
                    self.conversation.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": result["tool_use_id"],
                                "content": result["content"]
                            }
                            for result in tool_results
                        ]
                    })

                    # Get follow-up response
                    follow_up = self.client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=4096,
                        tools=self.tools,
                        messages=self.conversation
                    )

                    # Add follow-up to conversation
                    self.conversation.append({
                        "role": "assistant",
                        "content": follow_up.content
                    })

                    # Print follow-up response
                    for content_block in follow_up.content:
                        if content_block.type == "text" and content_block.text.strip():
                            print(f"\n🤖 Assistant: {content_block.text}")

            except Exception as e:
                print(f"\n❌ Error: {str(e)}")
                # Remove the last user message if there was an error
                if self.conversation and self.conversation[-1]["role"] == "user":
                    self.conversation.pop()

def main():
    """Main entry point."""
    # Check for API key
    if not os.getenv("ANTHROPIC_API_KEY"):
        print("❌ Error: ANTHROPIC_API_KEY environment variable not set")
        print("Please set it with: export ANTHROPIC_API_KEY='your-api-key'")
        sys.exit(1)

    # Create and run the agent
    agent = AgentLoop()
    agent.run()

if __name__ == "__main__":
    main()

